def _h_t110():
    b = _h_biz('biz_110')
    df = b['danh_sach_hoa_don'].copy()
    df = df[df['Mã bill'].notna()].copy()
    df['dt'] = _h_dates(df['Ngày giao dịch'])
    df['rev'] = _h_mnum(df['Tien hang'])
    st = df['Status'].astype(str).str.strip()
    df['st_norm'] = np.select([st.str.contains('hủy|huỷ|cancel', case=False, na=False), st.str.contains('trả|return', case=False, na=False)], ['cancel', 'return'], default='ok')
    return dict(hd=df)

